// During incremental marking, the mutator runs:
//   black.field = white;   // a black (scanned) object now points to a white one
// Without protection, the marker never re-visits `black`,
// so `white` stays white and is wrongly swept. What prevents this?

function sweep(colors) {
  // BUG: reclaims everything that is not black, but a grey object is still
  // on the marker's worklist (reached, scan pending) and is LIVE.
  const freed = [];
  for (const id of Object.keys(colors)) {
    if (colors[id] !== 'black') freed.push(id);
  }
  return freed.sort();
}

tasks.verify:
const colors = { root: 'black', a: 'grey', b: 'black', dead: 'white' };
const freed = sweep(colors);
const ok = freed.length === 1 && freed[0] === 'dead';
console.log(ok ? 'PASS' : 'FAIL freed=' + freed.join(','));

