// objects: id -> { color, fields: [referencedIds] }
function compact(objects) {
  const forwarding = new Map();   // old id -> new id
  let next = 0;

  // 1. relocate live objects, assign new addresses
  for (const [id, obj] of Object.entries(objects)) {
    if (obj.color === 'black') {
      forwarding.set(id, 'n' + next++);
    }
  }

  // 2. rewrite pointers in the relocated objects
  for (const [id, obj] of Object.entries(objects)) {
    obj.fields = obj.fields.map((ref) => forwarding.get(ref));
  }

  return forwarding;
}
